    const n = big ? 10000 : r.int(1, 5);
    const words = [];
    for (let i = 0; i < n; i++) words.push(r.str(r.int(1, big ? 20 : 3), big ? "abcdefghijklmnopqrstuvwxyz" : "abc"));
    if (big || r.bool(0.5)) {
      const rank = {}; for (let i = 0; i < 26; i++) rank[order[i]] = String.fromCharCode(97 + i);
      const key = w => w.split("").map(c => rank[c]).join("");
      words.sort((x, y) => key(x) < key(y) ? -1 : key(x) > key(y) ? 1 : 0);
      if (!big && r.bool(0.3) && n > 1) { const i = r.int(0, n - 2); [words[i], words[i + 1]] = [words[i + 1], words[i]]; }
    }
    return [words, order];
  }

