function isSortedByAlphabet(words: string[], order: string): boolean {
  const rank = new Array<number>(26);
  for (let i = 0; i < 26; i++) rank[order.charCodeAt(i) - 97] = i;
  for (let w = 0; w + 1 < words.length; w++) {
    const x = words[w], y = words[w + 1];
    let k = 0;
    while (k < x.length && k < y.length && x[k] === y[k]) k++;
    if (k === x.length || k === y.length) {
      if (x.length > y.length) return false; // y is a proper prefix of x
      continue;
    }
    if (rank[x.charCodeAt(k) - 97] > rank[y.charCodeAt(k) - 97]) return false;
  }
  return true;
}

