class Solution:
    def isSortedByAlphabet(self, words: List[str], order: str) -> bool:
        rank = {c: i for i, c in enumerate(order)}
        for x, y in zip(words, words[1:]):
            for a, b in zip(x, y):
                if a != b:
                    if rank[a] > rank[b]:
                        return False
                    break
            else:
                if len(x) > len(y):
                    return False
        return True

