function isSortedByAlphabet(words: string[], order: string): boolean {
  const map: Record<string, string> = {};
  for (let i = 0; i < 26; i++) map[order[i]] = String.fromCharCode(97 + i);
  const keys = words.map(w => Array.from(w, c => map[c]).join(""));
  for (let i = 0; i + 1 < keys.length; i++) if (keys[i] > keys[i + 1]) return false;
  return true;
}

